.hamburger {
  width: 30px;
  height: 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;

  &__line {
    width: 100%;
    height: 5px;
    background: #000;
    border-radius: 2px;
    transition: transform 0.25s ease, opacity 0.25s ease;
  }

  &--open {
    .hamburger__line {
      &:nth-child(1) {
        transform: translateY(9.5px) rotate(45deg);
      }

      &:nth-child(2) {
        opacity: 0;
      }

      &:nth-child(3) {
        transform: translateY(-9.5px) rotate(-45deg);
      }
    }
  }
}

